function peerResumeTicket(g){return{token:'native-peer-resume',proposal:{goalId:g.id,petId:g.spec.owner.petId,revision:g.revision,requestId:'resume-original-revision',provider:'ollama',leaseId:'same-lease',intent:g.spec.intent,criteria:g.spec.criteria,approvalScope:'resumeOriginalPeerExecution',resultingState:'leased',snapshot:{accounting:null,budget:null},peerResumption:{goalId:g.id,petId:g.spec.owner.petId,goalRevision:g.revision,leaseId:'same-lease',additionalAllowance:false,modelUseAuthorized:false,remaining:{modelCalls:0,toolCalls:1,outputBytes:1024},delegatedHeld:{modelCalls:1,toolCalls:1,outputBytes:2048},originalBudget:budget,lastReviewedDestination:{kind:'server',provider:'ollama',endpoint:'http://127.0.0.1:19009',model:'original-model'},model:'original-model',pendingSteps:[{taskId:'task',planId:'plan',stepId:'pending'}],receipts:[]}}};}
test('peer resume preserves original owner and lost ACK while inference is unavailable without metadata or execution',async()=>{
 for(const lost of[true,false]){
  const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,musicGoalPlan([{action:'pause'}]).steps),original=structuredClone(g),ticket=peerResumeTicket(original),sent=[];let release;
  f.transport.petRuntimePreparePeerResume=async value=>{sent.push(['prepare',structuredClone(value)]);await new Promise(resolve=>release=resolve);return{status:'review',ticket};};
  const work=a.preparePeerResume(g);g.spec.owner.petId='agent_codex';g.revision='different-view';release();await work;assert.equal(sent[0][1].petId,original.spec.owner.petId);assert.equal(sent[0][1].revision,original.revision);
  f.transport.petRuntimeRefreshReadiness=async(pet,id)=>{sent.push(['metadata',pet,id]);throw Error('configured inference unavailable');};let first=true;
  f.transport.petRuntimeConfirmRecovery=async value=>{sent.push(['confirm',structuredClone(value)]);if(first){first=false;if(lost)throw Error('peer ACK lost');return{status:'acknowledgementPending',receipt:{record:original,status:'uncertain'}};}return{status:'resumed',receipt:{record:{...original,state:'leased'},status:'unchanged'},lease:{id:'same-lease'},owned:true,executionAvailable:false};};
  await assert.rejects(a.confirmRecovery(g,true),lost?/ACK lost/:/precisa de confirmação/);assert.equal(a.recoveryReviews.get(g.id).ticket.token,ticket.token);
  f.transport.petRuntimeRefreshReadiness=async()=>{throw Error('ACK cannot resolve another model');};await a.confirmRecovery(g,true);
  const choices=sent.filter(([kind])=>kind==='confirm');assert.deepEqual(choices[0],choices[1]);assert.equal(choices[0][1].petId,original.spec.owner.petId);assert.equal(choices[0][1].revision,original.revision);assert.equal(sent.filter(([kind])=>kind==='metadata').length,0);assert.equal(a.recoveryReviews.size,0);assert.ok(!f.calls.some(([kind])=>['claim','respond','start-driver','run-recipe'].includes(kind)));
 }
});
