function fixture(){
 const calls=[];let goal;let next=0;const clone=v=>structuredClone(v),record=()=>({status:'durable',record:clone(goal)});let progress;
 const transport={
  async petRuntimeCreate(input){calls.push(['create',clone(input)]);goal={schemaVersion:1,id:'original-goal',revision:`r${++next}`,sequence:1,createdAt:1,updatedAt:1,spec:{requestId:input.requestId,owner:{petId:input.petId,provider:'ollama',adapter:'ollama',modelHint:'private-local'},context:{kind:'unbound'},intent:input.intent,criteria:clone(input.criteria)},state:'draft',tasks:[],plans:[],events:[],legacy:[],admissions:[]};return record();},
  async petRuntimeMutate(input){calls.push(['mutate',clone(input)]);assert.equal(input.goalId,goal.id);assert.equal(input.petId,goal.spec.owner.petId);assert.equal(input.revision,goal.revision);if(input.action.kind==='proposeTask')goal.tasks.push({id:'native-task',description:input.action.description,state:'proposed',planId:null});else if(input.action.kind==='proposePlan'){goal.plans.push({id:'native-plan',taskId:input.action.taskId,steps:input.action.steps.map((s,i)=>({...s,id:`native-step-${i+1}`,state:'proposed'}))});goal.tasks[0].planId='native-plan';}else if(input.action.kind==='pause')goal.state='stopping';goal.revision=`r${++next}`;return record();},
  async petRuntimePrepareContext(input){calls.push(['context',clone(input)]);goal.executionContext={conversationId:'private-goal-context',mode:input.mode};goal.revision=`r${++next}`;return record();},
  async petRuntimeRefreshReadiness(pet,id){calls.push(['metadata',{pet,id}]);return {};},
  async petRuntimePrepareAdmission(input){calls.push(['prepare',clone(input)]);return {status:'review',ticket:{token:'original-native-token',proposal:{goalId:input.goalId,revision:input.revision,owner:clone(goal.spec.owner),intent:goal.spec.intent,criteria:clone(goal.spec.criteria),budget:clone(input.budget),resolvedModel:'private-local',proposals:{tasks:goal.tasks,plans:goal.plans}}}};},
  async petRuntimeConfirmAdmission(input){calls.push(['confirm',clone(input)]);if(!input.approve)return {status:'declined'};goal.state='queued';goal.admissions=[{spec:{decisionId:'original-decision'},phase:'queued'}];goal.revision=`r${++next}`;return {status:'queued',receipt:record()};},
  async petRuntimeClaim(input){calls.push(['claim',clone(input)]);goal.state='leased';goal.admissions[0].lease={id:'original-lease'};goal.revision=`r${++next}`;return {owned:true,reservationOwned:true,executionAvailable:false,lease:{id:'original-lease'},receipt:record()};},
  async petRuntimeClaimStatus(pet,id){calls.push(['claim-status',{pet,id}]);return {source:'liveController',owned:true,current:false,lease:goal.admissions.at(-1)?.lease,record:clone(goal)};},
  async petRuntimeRespondOnce(input){calls.push(['respond',clone(input)]);return {text:'Persisted model text, not proof of completion',criteriaVerified:false,goalComplete:false};},
  async petRuntimeRequestRecipe(input){calls.push(['request-recipe',clone(input)]);progress={scope:{id:'original-recipe',goalId:goal.id,petId:input.petId,leaseId:input.leaseId,decisionId:'original-decision',planId:input.planId,steps:goal.plans[0].steps.map(s=>({stepId:s.id,grantId:`grant-${s.id}`}))},phase:'reviewed',verifiedSteps:0,totalSteps:goal.plans[0].steps.length,criteriaVerified:false,goalComplete:false,steps:[]};return {status:'granted',scope:progress.scope};},
  async petRuntimeRecipeProgress(input){calls.push(['read-recipe',clone(input)]);return clone(progress);},
  async petRuntimeRunRecipe(input){calls.push(['run-recipe',clone(input)]);goal.state='completed';progress={...progress,phase:'verified',criteriaVerified:true,goalComplete:true,verifiedSteps:progress.totalSteps};return {outcome:'goalCompleted',progress:clone(progress)};},
  async petRuntimeReleaseClaim(...input){calls.push(['release',clone(input)]);return record();},
  async petRuntimeResult(input){calls.push(['read-response',clone(input)]);return {status:'available',receipt:{text:'Durable native receipt'},criteriaVerified:false,goalComplete:false};},
  async petRuntimeCompleteRecipe(input){calls.push(['complete',clone(input)]);return record();},
  async petRuntimeRecoverStep(input){calls.push(['recover',clone(input)]);return {};},
 };
 return {transport,calls,get goal(){return clone(goal);},get progress(){return clone(progress);},setGoal(value){goal=clone(value);}};
}
