test('reopened native admission cleanup keeps original data consent and does not refresh models or accept new scope',async()=>{
 const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,musicGoalPlan([{action:'pause'}]).steps),sent=[];
 const proposal={goalId:g.id,revision:g.revision,owner:g.spec.owner,intent:g.spec.intent,criteria:g.spec.criteria,budget,preparedAt:100,expiresAt:200,memoryData:{requiredConsent:'boundedGoalContext'}};
 a.reviews.set(g.id,{status:'review',ticket:{token:'new-cleanup-alias',approvalScope:'confirmOriginalAdmission',proposal}});
 f.transport.petRuntimeRefreshReadiness=async()=>{throw Error('cleanup must not resolve or change a model');};f.transport.petRuntimeConfirmAdmission=async i=>{sent.push(structuredClone(i));return sent.length===1?{status:'authorityBlocked',reason:'busy',retryable:true}:{status:'queued',receipt:{status:'unchanged',record:g}};};
 await assert.rejects(a.confirmAdmission(g,true,'boundedGoalContext'),/não aceita um âmbito novo/);assert.equal(sent.length,0);
 await a.confirmAdmission(g,true);assert.equal(a.reviews.get(g.id).ticket.token,'new-cleanup-alias');await a.confirmAdmission({...g,revision:'later-ui-revision'},true);assert.deepEqual(sent[0],sent[1]);assert.equal(sent[0].revision,proposal.revision);assert.equal(sent[0].memoryConsent,undefined);assert.equal(a.reviews.size,0);assert.ok(!f.calls.some(([name])=>['metadata','claim','respond'].includes(name)));
});

