test('known metadata Busy may resume only the exact native pending claim without changing its caller or request',async()=>{
 for(const attack of[null,s=>s.lease.requestId='other',s=>s.record.revision='changed',s=>s.lease.decisionId='other',s=>s.lease.model='other',s=>s.lease.conversationId='other',s=>s.owned=true,s=>s.source='storedLease']){
  const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,[]);g.state='queued';g.admissions=[{spec:{schemaVersion:2,decisionId:'original-decision',resolvedModel:'private-local'}}];f.setGoal(g);const status={source:'liveController',owned:false,reservationOwned:true,record:structuredClone(g),lease:{goalId:g.id,sourceRevision:g.revision,requestId:'original-request',decisionId:'original-decision',provider:g.spec.owner.provider,model:'private-local',conversationId:g.executionContext.conversationId}};if(attack)attack(status);
  f.transport.petRuntimeRefreshReadiness=async()=>{throw Error('busy');};f.transport.petRuntimeClaimStatus=async()=>status;
  if(attack){await assert.rejects(a.claim(g,'original-request'),/busy/);assert.ok(!f.calls.some(c=>c[0]==='claim'));}else{await a.claim(g,'original-request');assert.deepEqual(f.calls.find(c=>c[0]==='claim')[1],{petId:'ai_ollama',goalId:g.id,revision:g.revision,requestId:'original-request'});}
 }
 for(const error of['storageUnavailable','conflict']){const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,[]);f.transport.petRuntimeRefreshReadiness=async()=>{throw Error(error);};await assert.rejects(a.claim(g,'original-request'),new RegExp(error));assert.ok(!f.calls.some(c=>['claim','claim-status'].includes(c[0])));}
});

const finiteBounds={deadlineAt:2_000_000,maxModelCalls:1,maxToolCalls:0,maxOutputBytes:4096,payment:'localOnly'};
const startReview=(g,b,wanted=true)=>({status:'review',ticket:{token:'exact-start',proposal:{goalId:g.id,revision:g.revision,owner:structuredClone(g.spec.owner),operation:'conversationRespond',intent:g.spec.intent,criteria:structuredClone(g.spec.criteria),budget:structuredClone(b),...(wanted?{executionStart:{schemaVersion:1,mode:'whenAvailable',scope:'finiteResponse'}}:{})}}});
