 f.transport.petRuntimeRefreshReadiness=async(pet,id)=>{seen.push(['metadata',pet,id]);await gate;throw Error('busy');};
 f.transport.petRuntimePrepareAdmission=async i=>{seen.push(['prepare',structuredClone(i)]);return startReview(original,expected);};
