 assert.deepEqual(seen,[['metadata',original.spec.owner.petId,original.id],['prepare',{petId:original.spec.owner.petId,goalId:original.id,revision:original.revision,requestId:'signed-start',budget:expected,start:'whenAvailable'}]]);assert.equal(a.reviews.get(original.id).ticket.proposal.executionStart.scope,'finiteResponse');assert.ok(!f.calls.some(([k])=>['claim','respond','start-driver'].includes(k)));
