test('memory correspondence captures its dedicated selection before model readiness and rejects received-context forwarding',async()=>{
 const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,[{description:'Own memory-backed proposal',postcondition:'Local DATA receipt'}]),sent=[];g.executionContext={mode:'dedicated',copiedMessages:0,memory:{schemaVersion:1,references:[{id:'original-note',revision:7}]}};f.transport.petRuntimePreparePlanning=async value=>{sent.push(structuredClone(value));return {status:'blocked',reason:'fixture'};};const limits={maxRounds:1,maxSteps:2,maxOutputBytes:2048,noProgressLimit:1};await a.preparePlanning(g,{...budget,maxModelCalls:1,maxToolCalls:2},limits,'memory-catalogue',false,'peerCorrespondenceMemoryV1');assert.equal(sent[0].catalog,'peerCorrespondenceMemoryV1');
 for(const patch of [{receivedRequest:{schemaVersion:6}},{mode:'snapshot'},{copiedMessages:1},{memory:undefined}]){const changed=copyGoal(g);Object.assign(changed.executionContext,patch);f.transport.petRuntimeRefreshReadiness=async()=>{throw Error('must not resolve unreviewed forwarding');};await assert.rejects(a.preparePlanning(changed,{...budget,maxModelCalls:1,maxToolCalls:2},limits,'invalid-memory',false,'peerCorrespondenceMemoryV1'),/contexto dedicado/);}assert.equal(sent.length,1);
 function copyGoal(g){return structuredClone(g);}
});


test('planned delegation captures one shared total budget and refuses selected or received contexts before readiness',async()=>{
 const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,[{description:'Propose bounded branches',postcondition:'No recipient authority from model text'}]),sent=[];g.executionContext={mode:'dedicated',copiedMessages:0};const bounds={...budget,maxModelCalls:3,maxToolCalls:6},limits={maxRounds:1,maxSteps:2,maxOutputBytes:2048,noProgressLimit:1};f.transport.petRuntimePreparePlanning=async value=>{sent.push(structuredClone(value));return {status:'blocked',reason:'fixture'};};await a.preparePlanning(g,bounds,limits,'shared-total',false,'peerDelegationV1');assert.equal(sent[0].catalog,'peerDelegationV1');assert.equal(sent[0].budget.maxModelCalls,3);assert.equal(sent[0].limits.maxRounds,1);
 for(const change of [{memory:{references:[{id:'private-note',revision:1}]}},{receivedRequest:{schemaVersion:6}},{mode:'snapshot'},{copiedMessages:1}]){const changed=structuredClone(g);Object.assign(changed.executionContext,change);f.transport.petRuntimeRefreshReadiness=async()=>{throw Error('must not resolve an unauthorized context');};await assert.rejects(a.preparePlanning(changed,bounds,limits,'no-forwarding',false,'peerDelegationV1'),/contexto dedicado/);}assert.equal(sent.length,1);
});

test('received iterative planning captures the same selected source/deadline and refuses widening before provider readiness',async()=>{
 const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,[{description:'Own received-data plan',postcondition:'Still unverified'}]),sent=[];
 const source={reference:{decisionId:'a'.repeat(32),messageId:'b'.repeat(32),scopeHash:'c'.repeat(64)},senderPetId:'ai_lmstudio',recipientPetId:'ai_ollama',deadlineAt:budget.deadlineAt-1000};
 g.spec.receivedFrom={body:{schemaVersion:6,purpose:'receivedPlannedPeerOwnGoalDataOnly',source}};g.executionContext={schemaVersion:8,mode:'dedicated',copiedMessages:0,receivedRequest:{schemaVersion:6,ownOriginHash:'d'.repeat(64),source:structuredClone(source)}};
 const bounds={...budget,deadlineAt:source.deadlineAt,maxModelCalls:4,maxToolCalls:8},limits={maxRounds:2,maxSteps:2,maxOutputBytes:2048,noProgressLimit:2};
 f.transport.petRuntimePreparePlanning=async value=>{sent.push(structuredClone(value));return{status:'blocked',reason:'native-fixture'};};await a.preparePlanning(g,bounds,limits,'received-source',false,'peerDelegationIterationV1');assert.equal(sent.length,1);assert.equal(sent[0].budget.deadlineAt,source.deadlineAt);assert.equal(sent[0].catalog,'peerDelegationIterationV1');
 f.transport.petRuntimeRefreshReadiness=async()=>{throw Error('source refusal must precede model readiness');};
 for(const mutate of [v=>{v.executionContext.receivedRequest.source.reference.messageId='f'.repeat(32);},v=>{v.executionContext.copiedMessages=1;},v=>{v.executionContext.receivedRequest=undefined;},v=>{v.spec.receivedFrom.body.delegation={allowance:{modelCalls:1}};}]){const changed=structuredClone(g);mutate(changed);await assert.rejects(a.preparePlanning(changed,bounds,limits,'refused-received',false,'peerDelegationIterationV1'),/consentimento R43/);}
 await assert.rejects(a.preparePlanning(g,{...bounds,deadlineAt:source.deadlineAt+1},limits,'widened-deadline',false,'peerDelegationIterationV1'),/consentimento R43/);assert.equal(sent.length,1);
});

test('funded planning reviews its exact incoming reservation and own DATA, including a single funded round',async()=>{
 for(const schema of [2,4,7]){
  const f=fixture(),a=new RuntimeGoalActions(()=>{},f.transport),g=await a.create(input,[{description:'Own selected delegated instruction',postcondition:'No self-certified result'}]);
  const source={reference:{decisionId:'a'.repeat(32),messageId:'b'.repeat(32),scopeHash:'c'.repeat(64)},senderPetId:'ai_lmstudio',recipientPetId:'ai_ollama',deadlineAt:budget.deadlineAt-1000},allowance={modelCalls:2,toolCalls:4,outputBytes:32768};
  g.spec.receivedFrom={body:{schemaVersion:schema,delegation:{schemaVersion:schema===2?1:2,ancestors:schema===2?['ai_lmstudio']:['agent_codex','ai_lmstudio'],maxDepth:3,allowance},source}};
  g.executionContext={schemaVersion:schema===7?9:schema===4?6:4,mode:'dedicated',copiedMessages:0,receivedRequest:{schemaVersion:schema,ownOriginHash:'d'.repeat(64),source:structuredClone(source)}};
  const bounds={...budget,deadlineAt:source.deadlineAt,maxModelCalls:2,maxToolCalls:4,maxOutputBytes:32768},limits={maxRounds:2,maxSteps:2,maxOutputBytes:2048,noProgressLimit:2};
  const ticket=sent=>{const t=planningTicket(g,sent),p=t.ticket.proposal;p.funding={schemaVersion:9,source:structuredClone(source),allowance:structuredClone(allowance),ownOriginHash:g.executionContext.receivedRequest.ownOriginHash};p.memoryData={requiredConsent:'boundedGoalContext',maxInputBytes:262144,receivedRequest:{selection:structuredClone(g.executionContext.receivedRequest)},destination:{kind:'server',provider:'ollama',endpoint:'http://127.0.0.1:19001/v1/chat/completions',model:p.resolvedModel}};return t;};
  let prepares=0;f.transport.petRuntimePreparePlanning=async sent=>{prepares++;return ticket(sent);};await a.preparePlanning(g,bounds,limits,'own-funded-planner',false,'peerDelegationIterationV1');assert.equal(a.reviews.get(g.id).ticket.proposal.funding.schemaVersion,9);
  await a.preparePlanning(g,{...bounds,maxModelCalls:1},{...limits,maxRounds:1,noProgressLimit:1},'own-single-funded-round',false,'peerDelegationIterationV1');assert.equal(prepares,2);
  for(const mutate of [p=>delete p.funding,p=>p.funding.schemaVersion=1,p=>p.funding.ownOriginHash='f'.repeat(64),p=>p.funding.source.reference.messageId='f'.repeat(32),p=>p.funding.allowance.modelCalls++,p=>p.memoryData.receivedRequest.selection.schemaVersion=1]){
   a.reviews.clear();f.transport.petRuntimePreparePlanning=async sent=>{const t=ticket(sent);mutate(t.ticket.proposal);return t;};await assert.rejects(a.preparePlanning(g,bounds,limits,'changed-native-review',false,'peerDelegationIterationV1'),/reserva|dados recebidos/);assert.equal(a.reviews.size,0);
  }
  f.transport.petRuntimeRefreshReadiness=async()=>{throw Error('rejected scope cannot query a provider');};
  for(const mutate of [b=>b.maxModelCalls++,b=>b.maxToolCalls++,b=>b.maxOutputBytes++,b=>b.deadlineAt++]){const b=structuredClone(bounds);mutate(b);await assert.rejects(a.preparePlanning(g,b,limits,'over-allocation',false,'peerDelegationIterationV1'),/reserva|consentimento R43/);}
  const missing=structuredClone(g);missing.executionContext.receivedRequest=undefined;await assert.rejects(a.preparePlanning(missing,bounds,limits,'missing-source',false,'peerDelegationIterationV1'),/seleção exata|consentimento R43/);assert.ok(!f.calls.some(([name])=>['confirm','claim','respond','start-driver'].includes(name)));
 }
});
